mapper.select:
select   
order by n.created_at desc, n.ncr_id desc
limit #{limit}

mapper.update:
update qms_ncr set defect_id = #{defectId}, nc_qty = #{ncQty}, description = #{description},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ncr_id = #{id} and status = 'OPEN' and row_ver = #{rowVer}

mapper.select:
select ncr_id, ncr_no, status from qms_ncr
 where ncr_id in #{id}
 order by ncr_id
